import os, sys, json, urllib.request, urllib.parse, time
KEY = os.environ.get("OPENALEX_API_KEY","")
def get(url):
    sep = '&' if '?' in url else '?'
    url = url + f"{sep}api_key={KEY}"
    for i in range(3):
        try:
            with urllib.request.urlopen(url, timeout=60) as r:
                return json.load(r)
        except Exception as e:
            time.sleep(2); err=e
    raise err
def oid(doi):
    w = get("https://api.openalex.org/works/doi:" + doi)
    return w["id"].split("/")[-1], w.get("cited_by_count"), w.get("title")
def abstract(w):
    ii = w.get("abstract_inverted_index")
    if not ii: return ""
    pos = {}
    for word, ps in ii.items():
        for p in ps: pos[p] = word
    return " ".join(pos[k] for k in sorted(pos))
def cites(ids, search=None, n=50, show_abs=False, page=1):
    f = "cites:" + "|".join(ids)
    url = f"https://api.openalex.org/works?filter={f}&per-page={n}&page={page}"
    if search: url += "&search=" + urllib.parse.quote(search)
    d = get(url)
    print(f"# count={d['meta']['count']}")
    for w in d["results"]:
        print(f"- {w.get('publication_year')} | {w.get('doi')} | {w.get('title')} | cit={w.get('cited_by_count')}")
        if show_abs: print("   ABS:", abstract(w)[:1200])
def search(q, n=25, show_abs=False, filt=None):
    url = f"https://api.openalex.org/works?search={urllib.parse.quote(q)}&per-page={n}"
    if filt: url += "&filter=" + filt
    d = get(url)
    print(f"# count={d['meta']['count']}")
    for w in d["results"]:
        print(f"- {w.get('publication_year')} | {w.get('doi')} | {w.get('title')} | cit={w.get('cited_by_count')}")
        if show_abs: print("   ABS:", abstract(w)[:1200])
def work(doi, show_abs=True):
    w = get("https://api.openalex.org/works/doi:" + doi)
    print(w["id"], w.get("publication_year"), w.get("doi"), w.get("title"), "cit=", w.get("cited_by_count"))
    if show_abs: print("   ABS:", abstract(w)[:2500])
if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "ids":
        for d in sys.argv[2:]:
            try: print(d, *oid(d))
            except Exception as e: print(d, "ERR", e)
    elif cmd == "cites":
        ids = sys.argv[2].split(","); s = sys.argv[3] if len(sys.argv)>3 and sys.argv[3] else None
        ab = len(sys.argv)>4 and sys.argv[4]=="abs"
        cites(ids, s, show_abs=ab)
    elif cmd == "search":
        ab = len(sys.argv)>3 and sys.argv[3]=="abs"
        search(sys.argv[2], show_abs=ab)
    elif cmd == "work":
        for d in sys.argv[2:]: work(d)
